const fs = require('fs');

function solve() {
    let buf;
    try {
        buf = fs.readFileSync(0);
    } catch (e) {
        return;
    }

    let pos = 0;
    const len = buf.length;

    function nextInt() {
        while (pos < len && buf[pos] <= 32) {
            pos++;
        }
        if (pos >= len) return null;
        let res = 0;
        while (pos < len && buf[pos] > 32) {
            res = res * 10 + (buf[pos] - 48);
            pos++;
        }
        return res;
    }

    const E = nextInt();
    if (E === null) return;
    const M = nextInt();
    const D = nextInt();

    const sameX = new Int32Array(M);
    const sameY = new Int32Array(M);
    for (let i = 0; i < M; i++) {
        sameX[i] = nextInt();
        sameY[i] = nextInt();
    }

    const diffU = new Int32Array(D);
    const diffV = new Int32Array(D);
    for (let i = 0; i < D; i++) {
        diffU[i] = nextInt();
        diffV[i] = nextInt();
    }

    const group = new Int32Array(E + 1);
    const numGroups = Math.floor(E / 3);
    for (let g = 0; g < numGroups; g++) {
        const a = nextInt();
        const b = nextInt();
        const c = nextInt();
        group[a] = g;
        group[b] = g;
        group[c] = g;
    }

    let violations = 0;
    for (let i = 0; i < M; i++) {
        if (group[sameX[i]] !== group[sameY[i]]) {
            violations++;
        }
    }

    for (let i = 0; i < D; i++) {
        if (group[diffU[i]] === group[diffV[i]]) {
            violations++;
        }
    }

    console.log(violations);
}

solve();
